//QuadTree Idea from @yalanlanlan

class Point{
    constructor(x,y){
        this.x=x;
        this.y=y;
    }
}

class Rectangle{
    constructor(x,y,w,h){
        this.x=x;
        this.y=y;
        this.w=w;
        this.h=h;
    }
    contains(point){
        return(point.x>=this.x-this.w && point.x<=this.x+this.w && point.y>=this.y-this.h && point.y<=this.y+this.h);
    }
}

class QuadTree{
    constructor(boundary, n){
        this.boundary=boundary;
        this.capacity=n;
        this.points=[];
        this.divided=false;

				colors = [[19,22,14], [235,235,235], [69,106,187], [233,206,49], [216,64,40]];
				probColors = [0.01, 0.51, 0.16, 0.16, 0.16];

			  this.color = chooseColor();
    }
    subdivide(){
        let x= this.boundary.x;
        let y= this.boundary.y;
        let w= this.boundary.w;
        let h= this.boundary.h;

        let ne = new Rectangle(x+w/2, y-h/2, w/2, h/2);
        this.northeast = new QuadTree(ne, this.capacity);
        let nw = new Rectangle(x-w/2, y-h/2, w/2, h/2);
        this.northwest = new QuadTree(nw, this.capacity);
        let se = new Rectangle(x+w/2, y+h/2, w/2, h/2);
        this.southeast = new QuadTree(se, this.capacity);
        let sw = new Rectangle(x-w/2, y+h/2, w/2, h/2);
        this.southwest = new QuadTree(sw, this.capacity);

        this.divided=true;

    }
    insert(point){
        if (!this.boundary.contains(point)){
            return false;
        }

        if (this.points.length<this.capacity){
            this.points.push(point);
            return true;
        }else{
            if(!this.divided){
                this.subdivide();
            }

            if(this.northeast.insert(point)){
                return true;
            }
            else if(this.northwest.insert(point)){
                return true;
            }
            else if(this.southeast.insert(point)){
                return true;
            }
            else if(this.southwest.insert(point)){
                return true;
            }

        }
    }
    show(){
        stroke(0);
        strokeWeight(thickness);
			  rectMode(CENTER);

				var color = this.color;
				fill(colors[color][0], colors[color][1], colors[color][2]);

        rect(this.boundary.x, this.boundary.y, this.boundary.w*2, this.boundary.h*2);
        if(this.divided){
            this.northeast.show();
            this.northwest.show();
            this.southeast.show();
            this.southwest.show();
        }
    }
}

